<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];
function c(array $e,string $p,string $db):PDO{return new PDO('mysql:host='.$e[$p.'_DB_HOST'].';port='.$e[$p.'_DB_PORT'].';dbname='.$db.';charset=utf8mb4',$e[$p.'_DB_USERNAME'],$e[$p.'_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function cols(PDO $p,string $db,string $table):array{$s=$p->prepare('SELECT column_name,column_type,is_nullable,column_default,extra FROM information_schema.columns WHERE table_schema=? AND table_name=? ORDER BY ordinal_position');$s->execute([$db,$table]);return $s->fetchAll();}
$target=c($env,'GPT','gatlas_dbp');$targetNames=$target->query("SELECT table_name FROM information_schema.tables WHERE table_schema='gatlas_dbp' AND table_type='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN);
$sources=[];foreach([['LEGADO_MODELO','green_atlas'],['LEGADO_SEGURANCA','green_atlas_seguranca']] as [$prefix,$db]){$p=c($env,$prefix,$db);$sources[$db]=['pdo'=>$p,'tables'=>$p->query("SELECT table_name FROM information_schema.tables WHERE table_schema=".$p->quote($db)." AND table_type='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN)];}
$plan=['target_tables'=>count($targetNames),'exact'=>[],'compatible_missing_target_columns'=>[],'incompatible'=>[],'security_transform'=>['usuarios','grupos','usuariosxgrupos','usuariosxunidades','usuariosxempresas','gruposxmenus','menusxconfiguracoes','menusxfuncionalidades','uxg','controleimportacao','migracao_solicitacoes','politicaemails']];
foreach($sources as $db=>$source){foreach($source['tables'] as $table){if(!in_array($table,$targetNames,true))continue;$src=cols($source['pdo'],$db,$table);$dst=cols($target,'gatlas_dbp',$table);$sc=array_map(fn($x)=>strtolower((string)($x['column_name']??$x['COLUMN_NAME'])),$src);$dc=array_map(fn($x)=>strtolower((string)($x['column_name']??$x['COLUMN_NAME'])),$dst);$missing=array_values(array_diff($dc,$sc));$extra=array_values(array_diff($sc,$dc));$key=$db.'.'.$table;if(!$missing&&!$extra)$plan['exact'][]=$key;elseif(!$extra)$plan['compatible_missing_target_columns'][$key]=$missing;else $plan['incompatible'][$key]=['source_extra'=>$extra,'target_missing'=>$missing];}}
$json=json_encode($plan,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$out=__DIR__.'/../docs/plano_dados_atlas_'.date('Ymd').'.json';file_put_contents($out,$json.PHP_EOL);echo $out.PHP_EOL;echo 'exact='.count($plan['exact']).' compatible='.count($plan['compatible_missing_target_columns']).' incompatible='.count($plan['incompatible']).PHP_EOL;
